// Generated from src/registry/sources/control-ui/recipes/audio-visualizer.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const audioVisualizerKnobs = [
  "--cui-audio-visualizer-bar-size",
  "--cui-audio-visualizer-bar-gap",
  "--cui-audio-visualizer-radius",
  "--cui-audio-visualizer-bar-radius",
  "--cui-audio-visualizer-bar-background",
  "--cui-audio-visualizer-line-fill",
  "--cui-audio-visualizer-line-stroke",
  "--cui-audio-visualizer-baseline-stroke",
] as const;
export type AudioVisualizerKnobStyle = Partial<Record<(typeof audioVisualizerKnobs)[number], string>>;

export function audioVisualizerPointCount(points = 28) {
  return Math.min(128, Math.max(1, Number.isFinite(points) ? Math.floor(points) : 28));
}

export function normalizeAudioLevel(level: number) {
  return Number.isFinite(level) ? Math.min(1, Math.max(0, level)) : 0;
}

export function audioVisualizerHistory(levels: ArrayLike<number>, points?: number, active = true) {
  const count = audioVisualizerPointCount(points);
  const start = Math.max(0, levels.length - count);
  const padding = Math.max(0, count - levels.length);
  return Array.from({ length: count }, (_, index) => ({
    key: `bar-${index}`,
    level: active && index >= padding ? normalizeAudioLevel(levels[start + index - padding] ?? 0) : 0,
  }));
}

export function audioVisualizerBands(levels: ArrayLike<number>, points?: number, active = true, mirrored = false) {
  const count = audioVisualizerPointCount(points);
  const bandCount = mirrored ? Math.ceil(count / 2) : count;
  const bands = Array.from({ length: bandCount }, (_, index) => {
    if (!active || levels.length === 0) return 0;
    const start = (index * levels.length) / bandCount;
    const end = ((index + 1) * levels.length) / bandCount;
    let total = 0;
    for (let sample = Math.floor(start); sample < Math.ceil(end); sample += 1) {
      const weight = Math.min(end, sample + 1) - Math.max(start, sample);
      total += normalizeAudioLevel(levels[sample] ?? 0) * weight;
    }
    return total / (end - start);
  });

  return Array.from({ length: count }, (_, index) => ({
    key: `band-${index}`,
    level: bands[mirrored ? Math.floor(Math.abs(index - (count - 1) / 2)) : index] ?? 0,
  }));
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { useLayoutEffect, useRef } from "react";
import type { AudioVisualizerKnobStyle } from "@/components/control-ui/knob-contracts/audio-visualizer-knobs";
import { audioVisualizerHistory } from "@/components/control-ui/lib/audio-visualizer-levels";
import { cn } from "@/components/control-ui/lib/cn";

export type AudioVisualizerProps = Omit<ComponentProps<"div">, "children" | "style"> & {
  levels: ArrayLike<number>;
  active?: boolean;
  points?: number;
  style?: CSSProperties & AudioVisualizerKnobStyle;
};

type AudioVisualizerLevelStyle = CSSProperties & Record<"--_audio-visualizer-level-opacity", string>;

const MIN_VISIBLE_LEVEL = 0.04;

type HistorySample = { levels: number[]; time: number; active: boolean };

function historyAdvanced(previous: HistorySample | null, next: HistorySample) {
  if (!previous?.active || !next.active || previous.levels.length !== next.levels.length || next.levels.length < 2) return false;
  const moved = previous.levels.slice(1).every((level, index) => level === next.levels[index]);
  const changed = previous.levels.some((level, index) => level !== next.levels[index]);
  return moved && changed;
}

export function AudioVisualizer({ levels, points, active = true, className, style, ...props }: AudioVisualizerProps) {
  const visible = audioVisualizerHistory(levels, points, active);
  const labelled = Boolean(props["aria-label"] || props["aria-labelledby"]);
  const trackRef = useRef<HTMLSpanElement | null>(null);
  const firstBarRef = useRef<HTMLSpanElement | null>(null);
  const previousSample = useRef<HistorySample | null>(null);

  useLayoutEffect(() => {
    const next = { levels: visible.map(({ level }) => level), time: performance.now(), active };
    const previous = previousSample.current;
    previousSample.current = next;
    const track = trackRef.current;
    const firstBar = firstBarRef.current;
    if (!track || !firstBar || !historyAdvanced(previous, next) || document.hidden) return;
    const duration = next.time - (previous?.time ?? next.time);
    if (duration < 16 || duration > 250 || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const direction = getComputedStyle(track).direction === "rtl" ? -1 : 1;
    const pitch = (track.clientWidth - firstBar.clientWidth) / (visible.length - 1);
    const animation = track.animate([{ transform: `translateX(${pitch * direction}px)` }, { transform: "translateX(0)" }], {
      duration,
      easing: "linear",
    });
    return () => animation.cancel();
  }, [visible, active]);

  return (
    <div
      data-control-ui="audio-visualizer"
      data-control-family="audio-visualizer"
      data-slot="root"
      data-variant="bars"
      data-active={active ? "true" : undefined}
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn("shrink-0 overflow-hidden mask-x-from-90%", className)}
      style={style}
      {...props}
    >
      <span
        ref={trackRef}
        data-control-ui="audio-visualizer"
        data-control-family="audio-visualizer"
        data-slot="track"
        data-active={active ? "true" : undefined}
        className="flex size-full items-stretch justify-between"
      >
        {visible.map(({ key, level }) => {
          const perceptualLevel = Math.sqrt(level);
          const visibleLevel = MIN_VISIBLE_LEVEL + perceptualLevel * (1 - MIN_VISIBLE_LEVEL);
          const levelStyle: AudioVisualizerLevelStyle = {
            "--_audio-visualizer-level-opacity": `${0.48 + perceptualLevel * 0.52}`,
            clipPath: `inset(${(1 - visibleLevel) * 50}% 0 round var(--cui-audio-visualizer-bar-radius))`,
          };

          return (
            <span
              key={key}
              ref={key === "bar-0" ? firstBarRef : undefined}
              data-control-ui="audio-visualizer"
              data-control-family="audio-visualizer"
              data-slot="bar-track"
              className="flex items-center"
            >
              <span
                data-control-ui="audio-visualizer"
                data-control-family="audio-visualizer"
                data-slot="bar"
                className="block h-full w-full"
                style={levelStyle}
              />
            </span>
          );
        })}
      </span>
    </div>
  );
}

@layer components {
  :where([data-control-family="audio-visualizer"][data-variant]) {
    --cui-audio-visualizer-radius: var(--radius-control);
    --cui-audio-visualizer-bar-background: oklch(from var(--primary) l c h / 0.8);
    --cui-audio-visualizer-bar-radius: var(--radius-control);
    --cui-audio-visualizer-bar-size: calc(var(--spacing) * 1);
    --cui-audio-visualizer-bar-gap: 1px;
    --cui-audio-visualizer-line-fill: oklch(from var(--primary) l c h / 0.18);
    --cui-audio-visualizer-line-stroke: oklch(from var(--primary) l c h / 0.8);
    --cui-audio-visualizer-baseline-stroke: oklch(from var(--border) l c h / 0.55);
    --_audio-visualizer-inline-sign: 1;
  }
  :where([data-control-family="audio-visualizer"][data-variant]:dir(rtl)) {
    --_audio-visualizer-inline-sign: -1;
  }
  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant]) {
    block-size: calc(var(--spacing) * 7);
    inline-size: calc(var(--spacing) * 44);
    padding-inline: calc(var(--spacing) * 1.5);
    --_audio-visualizer-bar-track-filter: none;
    border-radius: var(--cui-audio-visualizer-radius);
  }

  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant="bars"]) {
    padding-block: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"]) {
    gap: var(--cui-audio-visualizer-bar-gap);
    opacity: 0.55;
    transition: opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"][data-active="true"]) {
    opacity: 1;
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
    inline-size: var(--cui-audio-visualizer-bar-size);
    min-inline-size: 0;
    flex-shrink: 1;
    transition:
      opacity var(--duration-base) var(--ease-emphasized),
      filter var(--duration-base) var(--ease-emphasized),
      translate var(--duration-base) var(--ease-emphasized);
    filter: var(--_audio-visualizer-bar-track-filter);
  }

  @starting-style {
    :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
      opacity: 0;
      --_audio-visualizer-bar-track-filter: blur(var(--blur-xs));
      filter: var(--_audio-visualizer-bar-track-filter);
      translate: calc(var(--spacing) * var(--_audio-visualizer-inline-sign)) 0;
    }
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar"]) {
    background: var(--cui-audio-visualizer-bar-background);
    border-radius: var(--cui-audio-visualizer-bar-radius);
    opacity: var(--_audio-visualizer-level-opacity);
    transition:
      clip-path var(--duration-base) var(--ease-standard),
      opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="baseline"]) {
    stroke: var(--cui-audio-visualizer-baseline-stroke);
  }

  :where([data-control-family="audio-visualizer"][data-slot="waveform"]) {
    fill: var(--cui-audio-visualizer-line-fill);
    stroke: var(--cui-audio-visualizer-line-stroke);
    transition: d var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bars"][data-active="true"] [data-slot="bar"]) {
    transition: none;
  }

  :where([data-control-family="audio-visualizer"][data-variant="line"]:not([data-active="true"]) [data-slot="waveform"]) {
    opacity: 0;
  }

  :where([data-control-family="audio-visualizer"][data-variant="line"]:not([data-active="true"]) [data-slot="baseline"]) {
    stroke-dasharray: 1 4;
    stroke-linecap: round;
  }

  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant="bar"]) {
    --cui-audio-visualizer-bar-size: calc(var(--spacing) * 1.5);
    --cui-audio-visualizer-bar-gap: calc(var(--spacing) * 0.75);
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"] [data-slot="track"]) {
    display: flex;
    block-size: 100%;
    align-items: center;
    justify-content: center;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="start"] [data-slot="track"]) {
    align-items: flex-start;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="end"] [data-slot="track"]) {
    align-items: flex-end;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"] [data-slot="bar"]) {
    min-inline-size: 0;
    max-inline-size: var(--cui-audio-visualizer-bar-size);
    flex: 1;
    transform-origin: center;
    transition:
      height var(--duration-fast) var(--ease-standard),
      opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="start"] [data-slot="bar"]) {
    transform-origin: top;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="end"] [data-slot="bar"]) {
    transform-origin: bottom;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-idle="pulse"]:not([data-active="true"]) [data-slot="bar"]) {
    animation: cui-audio-bar-pulse calc(var(--duration-slow) * 4) var(--ease-standard) infinite;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-idle="wave"]:not([data-active="true"]) [data-slot="bar"]),
  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-loading="true"] [data-slot="bar"]) {
    animation: cui-audio-bar-pulse calc(var(--duration-slow) * 4) var(--ease-standard) infinite;
    animation-delay: var(--_audio-visualizer-delay);
  }

  @keyframes cui-audio-bar-pulse {
    0%,
    100% {
      transform: scaleY(1);
    }
    50% {
      transform: scaleY(4);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="audio-visualizer"] [data-slot]) {
      animation: none;
      transition: none;
    }
  }
}

@property --cui-audio-visualizer-bar-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 4px;
}

@property --cui-audio-visualizer-bar-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 1px;
}

